<script lang="ts">
  import { page } from '$app/state';
  import Icon from '$lib/components/Icon.svelte';
  import { getAsset } from '$lib/data/marketplace';
  import { buyerOrders, recordDownload, requestRefund } from '$lib/stores/buyer';
  let refundSlug=''; let refundReason=''; let refundOpen=false;
  $: order=$buyerOrders.find((entry)=>entry.id===page.params.id);
  function openRefund(slug:string){refundSlug=slug;refundReason='';refundOpen=true;}
  function submitRefund(){if(order&&refundSlug&&refundReason.trim()){requestRefund(order.id,refundSlug,refundReason.trim());refundOpen=false;}}
</script>
<svelte:head><title>{order ? `${order.id} — AssetGuru` : 'Order — AssetGuru'}</title></svelte:head>
{#if order}
<header class="page-head"><div><a href="/account/orders">← All orders</a><span class="eyebrow">Order receipt</span><h1>{order.id}</h1><p>Placed {order.date} · {order.status}</p></div><button class="button button-secondary" type="button" onclick={()=>window.print()}><Icon name="download" size={17}/> Print receipt</button></header>
<div class="order-grid">
  <section class="items glass"><div class="panel-head"><div><span class="eyebrow">Licensed products</span><h2>{order.items.length} {order.items.length===1?'asset':'assets'}</h2></div><span class="status">{order.status}</span></div>{#each order.items as line}{#if getAsset(line.slug)}{@const asset=getAsset(line.slug)!}<article class="line"><img src={asset.image} alt=""/><div class="copy"><a href={`/marketplace/${asset.slug}`}><h3>{asset.title}</h3></a><a href={`/creators/${asset.creatorSlug}`}>{asset.creator} ✓</a><div><span>{line.licence==='extended'?'Extended team':'Standard commercial'}</span><span>Purchased v{line.version}</span><span>{asset.downloadSize}</span></div>{#if line.refundStatus}<em>{line.refundStatus} refund request</em>{/if}</div><strong>{line.price===0?'Free':`£${line.price.toFixed(2)}`}</strong><div class="actions"><button class="button button-primary" type="button" onclick={()=>recordDownload(asset.slug,asset.version)}><Icon name="download" size={16}/> Download v{asset.version}</button><a class="button button-secondary" href={`/account/support?product=${asset.slug}&order=${order.id}`}><Icon name="support" size={16}/> Support</a>{#if !line.refundStatus}<button class="refund" type="button" onclick={()=>openRefund(asset.slug)}>Request refund</button>{/if}</div></article>{/if}{/each}</section>
  <aside><section class="summary glass"><span class="eyebrow">Payment summary</span><h2>Receipt</h2><dl><div><dt>Subtotal</dt><dd>£{order.subtotal.toFixed(2)}</dd></div><div><dt>VAT</dt><dd>£{order.vat.toFixed(2)}</dd></div><div class="total"><dt>Total</dt><dd>£{order.total.toFixed(2)}</dd></div></dl><p><Icon name="lock" size={16}/><span><b>{order.payment}</b><small>Payment reference stored with this order.</small></span></p></section><section class="licence glass"><Icon name="shield" size={27}/><h3>Licence record</h3><p>Your rights are tied to this order and remain available in your AssetGuru library. Downloading an update does not remove access to eligible previous versions.</p><a href="/support">Read buyer terms →</a></section></aside>
</div>
{#if refundOpen}<div class="modal-backdrop" role="presentation" onclick={(event)=>{if(event.target===event.currentTarget)refundOpen=false;}}><form class="modal glass" onsubmit={(event)=>{event.preventDefault();submitRefund();}}><button class="close" type="button" aria-label="Close" onclick={()=>refundOpen=false}><Icon name="close" size={18}/></button><span class="eyebrow">Refund request</span><h2>{getAsset(refundSlug)?.title}</h2><p>Explain what is wrong or how the listing differed from your expectation. AssetGuru will preserve the exact purchased version and order context.</p><label>Reason<textarea bind:value={refundReason} required minlength="20" placeholder="Give us enough detail to review the request fairly."></textarea></label><button class="button button-primary" type="submit">Submit refund request</button></form></div>{/if}
{:else}<div class="missing glass"><Icon name="alert" size={42}/><h1>Order not found.</h1><a class="button button-primary" href="/account/orders">Return to orders</a></div>{/if}
