.summary p b{color:#f5f8ff;font-size:9px}.summary p small{margin-top:3px;color:#718096;font-size:7px}.licence{margin-top:14px;color:#8b5cf6}.licence h3{color:#f5f8ff}.licence p{color:#aab5c8;font-size:9px;line-height:1.6}.licence a{color:#00e5ff;font-size:8px}.modal-backdrop{position:fixed;z-index:80;inset:0;display:grid;place-items:center;padding:20px;background:rgb(2 4 13/.8);backdrop-filter:blur(12px)}.modal{position:relative;width:min(560px,100%);padding:27px;border-radius:17px}.modal .close{position:absolute;top:13px;right:13px;width:38px;height:38px;display:grid;place-items:center;border:1px solid #183352;border-radius:9px;color:#aab5c8;background:#07111f;cursor:pointer}.modal h2{font-size:25px}.modal p{color:#aab5c8;font-size:10px;line-height:1.65}.modal label{display:grid;gap:7px;color:#aab5c8;font-size:9px}.modal textarea{min-height:130px;padding:12px;border:1px solid #183352;border-radius:9px;outline:0;color:#f5f8ff;background:#050a16;resize:vertical}.modal textarea:focus{border-color:#00e5ff}.modal .button{width:100%;margin-top:12px}.missing{max-width:700px;margin:70px auto;padding:65px;text-align:center;border-radius:18px;color:#ff7a9e}.missing .button{display:inline-flex;width:auto}
  @media(max-width:950px){.order-grid{grid-template-columns:1fr}.summary{position:static}.line{grid-template-columns:120px 1fr auto}.line>img{width:120px}.actions{grid-column:1/-1}}@media(max-width:620px){.page-head{align-items:start;flex-direction:column}.line{grid-template-columns:1fr}.line>img{width:100%;height:auto;aspect-ratio:16/9}.line>strong{grid-row:1;justify-self:end}.actions{display:grid}.actions .button{width:100%}}
</style>
